// 이번 문서 묶음의 실제 짧은 검사 원출력 보존. 제품 장시간/UI 실행에는 사용하지 않는다.
import fs from 'node:fs';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
const root='/Users/dhseo/Workspace/mediaServer',temp='/private/tmp/media-server-vlm-results-docs-y37u3q';
const [id,command,...args]=process.argv.slice(2);
if(!/^[a-z0-9-]+$/.test(id||'')||!command)throw new Error('실행 ID/명령 필요');
const out=path.join(temp,id+'.json');
if(fs.existsSync(out))throw new Error('기존 실행 덮어쓰기 금지');
const startedAt=new Date().toISOString(),start=Date.now();
const r=spawnSync(command,args,{cwd:root,encoding:'utf8',env:{...process.env,TMPDIR:temp},timeout:300000,maxBuffer:64*1024*1024});
const result={id,command,args,startedAt,endedAt:new Date().toISOString(),elapsedMs:Date.now()-start,exit:r.status,signal:r.signal,error:r.error?{code:r.error.code,message:r.error.message}:null,stdout:r.stdout||'',stderr:r.stderr||''};
fs.writeFileSync(out,JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({...result,stdout:result.stdout.slice(-5000),stderr:result.stderr.slice(-2000)}));
process.exit(r.status??1);
